mapper.update:
UPDATE menu
SET parent_id = #{parentId}, name = #{name}, path = #{path}, component = #{component},
    query = #{query}, is_frame = #{isFrame}, route_name = #{routeName}, menu_type = #{menuType},
    is_cache = #{isCache}, icon = #{icon}, permission_code = #{permissionCode},
    sort_order = #{sortOrder}, visible = #{visible}, status = #{status}
WHERE id = #{id}

mapper.select:
SELECT COUNT(*) FROM role_permission rp
INNER JOIN permission p ON rp.permission_id = p.id
WHERE p.code = #{permissionCode}
